//! THEMES-SYNC.md: the shared vectors (`testvectors/themes-sync/`, generated by the web reference
//! `tools/theme-lib/gen-sync-vectors.mjs`) reproduce byte for byte, the merge laws hold on generated documents, and the
//! save stamps keep their promises — the reference's `src/theme/sync.test.ts`, test for test.

mod common;

use common::{crate_dir, sha256_hex, sorted_files, vec_dir, Mulberry32};
use serde_json::{json, Map, Value};
use std::cmp::Ordering;
use std::fs;
use tinhat_theme::sync::{
    cmp_doc, cmp_key, legacy_choice, list_themes, merge_themes, project_choice, read_choice, read_themes,
    reassert_delay_ms, retry_delay_ms, save_choice, save_theme, simulate, stamps, unique_theme_id, KnownThemes, Read,
    THEMES_FORMAT,
};
use tinhat_theme::{canon_json, parse_json, pretty_json, resolve_theme, TokensSpec};

fn library() -> Value {
    parse_json(&fs::read_to_string(crate_dir().join("themes-library.json")).unwrap()).unwrap()
}

fn lib_by_id(lib: &Value) -> std::collections::HashMap<String, Value> {
    lib["themes"].as_array().unwrap().iter().map(|t| (t["id"].as_str().unwrap().to_string(), t.clone())).collect()
}

fn tokens() -> TokensSpec {
    TokensSpec::from_json(&parse_json(&fs::read_to_string(crate_dir().join("tokens.json")).unwrap()).unwrap()).unwrap()
}

/// `Object.fromEntries(entries.map((e) => [e.id, e]))` — a later entry with the same key wins; a missing id is the
/// key "undefined" (the reference's harness).
fn known_of(entries: Option<&Value>) -> Option<KnownThemes> {
    let entries = entries?.as_array()?;
    let mut m = KnownThemes::new();
    for e in entries {
        let key = match e.get("id") {
            Some(Value::String(s)) => s.clone(),
            Some(Value::Number(n)) => n.to_string(),
            Some(Value::Bool(b)) => b.to_string(),
            Some(Value::Null) => "null".into(),
            _ => "undefined".into(),
        };
        m.insert(key, e.clone());
    }
    Some(m)
}

fn opt(v: &Value, k: &str) -> Option<Value> {
    v.get(k).cloned()
}

fn run(v: &Value, by_id: &std::collections::HashMap<String, Value>, spec: &TokensSpec) -> Value {
    match v["kind"].as_str().unwrap() {
        "choice-read" => {
            let r = read_choice(v.get("value"));
            match r {
                Read::Ignore => json!({ "kind": "ignore" }),
                Read::Newer(d) => json!({ "kind": "newer", "doc": Value::Object(d) }),
                Read::Ok(d) => json!({ "kind": "ok", "doc": Value::Object(d) }),
            }
        }
        "choice-save" => {
            let known = opt(v, "known").filter(|k| !k.is_null());
            let known = known.as_ref().and_then(Value::as_object);
            let now = v["now"].as_f64().unwrap_or(f64::NAN);
            save_choice(v.get("raw"), known, v.get("patch"), v.get("fallback"), now, v["by"].as_str().unwrap_or("")).to_json()
        }
        "choice-project" => {
            let content = v["choice"].as_object().unwrap();
            let p = project_choice(content, |id| by_id.get(id), |t| resolve_theme(&Value::Object(t.clone()), spec).is_ok());
            let mut out = json!({
                "source": p.source.as_str(),
                "overrides": p.overrides.as_str(),
                "sounds": p.sounds,
                "icons": p.icons,
                "soundsRaw": p.sounds_raw,
                "iconsRaw": p.icons_raw,
                "themeId": p.theme_id,
            });
            if let Some(t) = &p.theme {
                out["themeSha256"] = Value::String(sha256_hex(canon_json(&Value::Object(t.clone())).as_bytes()));
            }
            out
        }
        "themes-read" => {
            let r = read_themes(v.get("value"));
            match &r {
                Read::Ignore => json!({ "kind": "ignore" }),
                _ => {
                    let doc = Value::Object(r.doc().unwrap().clone());
                    let list: Vec<Value> = list_themes(Some(&doc)).iter().map(|e| e["id"].clone()).collect();
                    json!({ "kind": r.kind(), "list": list })
                }
            }
        }
        "themes-save" => {
            let known = known_of(v.get("known"));
            save_theme(v.get("raw"), known.as_ref(), v["save"].as_object().unwrap()).to_json()
        }
        "themes-merge" => {
            let known = known_of(v.get("known"));
            let (doc, too_large) = merge_themes(v.get("raw"), known.as_ref(), v.get("justSaved").and_then(Value::as_str));
            json!({ "doc": Value::Object(doc), "tooLarge": too_large })
        }
        "sync" => simulate(v),
        k => panic!("unknown vector kind {k}"),
    }
}

#[test]
fn themes_sync_vectors_byte_for_byte() {
    let lib = library();
    let by_id = lib_by_id(&lib);
    let spec = tokens();
    let dir = vec_dir().join("themes-sync");
    let files: Vec<_> = sorted_files(&dir).into_iter().filter(|f| f.extension().is_some_and(|e| e == "json")).collect();
    assert!(files.len() >= 100, "only {} vectors", files.len());
    let mut kinds = std::collections::BTreeMap::<String, usize>::new();
    let mut bad = Vec::new();
    for f in &files {
        let text = fs::read_to_string(f).unwrap();
        let mut v = parse_json(&text).unwrap();
        *kinds.entry(v["kind"].as_str().unwrap().to_string()).or_default() += 1;
        let got = run(&v, &by_id, &spec);
        // the file rebuilt from the port's result must be the file (pretty canonical JSON)
        v["expect"] = got;
        let again = pretty_json(&v);
        if again != text {
            let name = f.file_name().unwrap().to_string_lossy().to_string();
            let line = text.lines().zip(again.lines()).position(|(a, b)| a != b).map(|i| i + 1).unwrap_or(0);
            bad.push(format!("{name}: first difference at line {line}"));
        }
    }
    assert!(bad.is_empty(), "{} of {} themes-sync vectors differ:\n{}", bad.len(), files.len(), bad.join("\n"));
    for k in ["choice-read", "choice-save", "choice-project", "themes-read", "themes-save", "themes-merge", "sync"] {
        assert!(kinds.contains_key(k), "no {k} vectors");
    }
    eprintln!("themes-sync vectors: {}/{} byte-identical {kinds:?}", files.len(), files.len());
}

// ---- the merge laws (§4.5) on generated documents ------------------------------------------------------------------

const IDS: [&str; 5] = ["a", "b", "c", "d", "e"];
const DEVS: [&str; 3] = ["D1", "D2", "D3"];

fn random_doc(r: &mut Mulberry32, nord_palette: &Value) -> Value {
    let mut themes = Vec::new();
    let n = r.below(6);
    for _ in 0..n {
        let id = IDS[r.below(IDS.len())];
        let saved_at = r.below(4);
        let rev = r.below(3);
        let by = DEVS[r.below(DEVS.len())];
        if r.next() < 0.3 {
            themes.push(json!({ "id": id, "savedAt": saved_at, "rev": rev, "by": by, "deleted": true }));
        } else {
            let name = format!("N{}", r.below(3));
            let theme = json!({ "format": "tinhat-theme", "v": 1, "id": id, "name": name, "palette": nord_palette });
            let mut e = json!({ "id": id, "savedAt": saved_at, "rev": rev, "by": by, "theme": theme.clone() });
            if r.next() < 0.3 {
                let mut old = theme;
                old["name"] = json!("old");
                e["previous"] = json!({ "savedAt": 0, "rev": 0, "by": "", "theme": old });
            }
            themes.push(e);
        }
    }
    json!({ "format": THEMES_FORMAT, "v": 1, "themes": themes })
}

/// `Object.fromEntries((doc.themes ?? []).map((e, i) => [`k${i}`, e]))`
fn entries_map(doc: &Map<String, Value>) -> KnownThemes {
    let mut m = KnownThemes::new();
    if let Some(Value::Array(a)) = doc.get("themes") {
        for (i, e) in a.iter().enumerate() {
            m.insert(format!("k{i}"), e.clone());
        }
    }
    m
}

fn merged(a: &Value, b: &Map<String, Value>) -> Map<String, Value> {
    merge_themes(Some(a), Some(&entries_map(b)), None).0
}

#[test]
fn merge_themes_is_a_join() {
    let lib = library();
    let nord = lib_by_id(&lib)["nord"]["palette"].clone();
    let mut r = Mulberry32::new(20260927);
    let c = |m: &Map<String, Value>| canon_json(&Value::Object(m.clone()));
    for i in 0..2000 {
        let a = random_doc(&mut r, &nord);
        let b = random_doc(&mut r, &nord);
        let cc = random_doc(&mut r, &nord);
        let (ao, bo, co) = (a.as_object().unwrap(), b.as_object().unwrap(), cc.as_object().unwrap());
        let ab = merged(&a, bo);
        let ba = merged(&b, ao);
        assert_eq!(c(&ab), c(&ba), "commutative #{i}");
        let ab_c = merged(&Value::Object(ab.clone()), co);
        let a_bc = merged(&a, &merged(&b, co));
        assert_eq!(c(&ab_c), c(&a_bc), "associative #{i}");
        assert_eq!(c(&merged(&Value::Object(ab.clone()), bo)), c(&ab), "idempotent #{i}");
        assert_eq!(c(&merged(&Value::Object(ab.clone()), &ab)), c(&ab), "self #{i}");
    }
}

fn o(v: Value) -> Map<String, Value> {
    v.as_object().unwrap().clone()
}

#[test]
fn the_order_key() {
    let e = |saved_at: i64, rev: i64, by: &str, name: &str| {
        o(json!({ "id": "a", "savedAt": saved_at, "rev": rev, "by": by, "theme": { "id": "a", "name": name } }))
    };
    assert_eq!(cmp_doc(&e(2, 0, "A", "x"), &e(1, 9, "Z", "x")), Ordering::Greater);
    assert_eq!(cmp_doc(&e(1, 2, "A", "x"), &e(1, 1, "Z", "x")), Ordering::Greater);
    assert_eq!(cmp_doc(&e(1, 1, "B", "x"), &e(1, 1, "A", "x")), Ordering::Greater);
    assert_eq!(cmp_doc(&e(1, 1, "A", "y"), &e(1, 1, "A", "x")), Ordering::Greater);
    // invalid fields read as 0 / 0 / ""
    assert_eq!(cmp_key(&o(json!({ "id": "a", "savedAt": -1, "rev": 1.5, "by": 3 })), &o(json!({ "id": "b" }))), Ordering::Equal);
}

#[test]
fn a_save_always_beats_its_base() {
    let mut r = Mulberry32::new(7);
    for _ in 0..500 {
        let base = o(json!({
            "savedAt": (r.next() * 1e12).floor(),
            "rev": (r.next() * 1e5).floor(),
            "by": "X",
        }));
        let s = stamps(Some(&base), (r.next() * 1e12).floor(), "A");
        let got = o(json!({ "savedAt": s.0, "rev": s.1, "by": s.2 }));
        assert_eq!(cmp_doc(&got, &base), Ordering::Greater);
    }
    let s = stamps(None, 5.0, "A");
    assert_eq!(json!({ "savedAt": s.0, "rev": s.1, "by": s.2 }), json!({ "savedAt": 5, "rev": 1, "by": "A" }));
}

#[test]
fn legacy_choice_goose_or_oled() {
    let c = |x: Option<&str>| canon_json(&Value::Object(legacy_choice(x)));
    assert_eq!(c(Some("goose")), canon_json(&json!({ "theme": "goose", "sounds": "goose", "icons": "duotone" })));
    for v in [None, Some("oled"), Some(""), Some("dracula"), Some("GOOSE")] {
        assert_eq!(c(v), canon_json(&json!({ "theme": "oled", "sounds": "default", "icons": "duotone" })), "{v:?}");
    }
}

#[test]
fn unique_theme_ids() {
    let lib = library();
    let by_id = lib_by_id(&lib);
    let mut taken: std::collections::HashSet<String> = ["dracula", "dracula-2", "nord"].iter().map(|s| s.to_string()).collect();
    let long = "x".repeat(64);
    let t = |taken: &std::collections::HashSet<String>| {
        let taken = taken.clone();
        let by_id = &by_id;
        move |id: &str| taken.contains(id) || by_id.contains_key(id)
    };
    assert_eq!(unique_theme_id("my-theme", t(&taken)), "my-theme");
    assert_eq!(unique_theme_id("dracula", t(&taken)), "dracula-3");
    assert_eq!(unique_theme_id("nord", t(&taken)), "nord-2");
    taken.insert(long.clone());
    assert_eq!(unique_theme_id(&long, t(&taken)), format!("{}-2", "x".repeat(62)));
    assert_eq!(unique_theme_id("Bad Id", t(&taken)), "theme");
}

#[test]
fn timing_helpers() {
    for d in ["A", "QWERTYUIOP", "", &"x".repeat(64)] {
        let ms = reassert_delay_ms(d);
        assert!(ms <= 2000);
        assert_eq!(reassert_delay_ms(d), ms);
    }
    let got: Vec<u64> = [0, 1, 2, 3, 8, 9, 30].iter().map(|&a| retry_delay_ms(a)).collect();
    assert_eq!(got, vec![1000, 2000, 4000, 8000, 256000, 300000, 300000]);
}

#[test]
fn every_favourite_projects_from_the_library() {
    let lib = library();
    let by_id = lib_by_id(&lib);
    let spec = tokens();
    for f in lib["favourites"].as_array().unwrap() {
        let id = f.as_str().unwrap();
        let p = project_choice(&o(json!({ "theme": id })), |x| by_id.get(x), |t| resolve_theme(&Value::Object(t.clone()), &spec).is_ok());
        assert_eq!(p.source.as_str(), "library", "{id}");
    }
}
